manufacturer = value['Manufacturer'].iloc[0].upper() if 'Manufacturer' in value.columns else ''
seq_variant = str(value['SequenceVariant'].iloc[0]) if 'SequenceVariant' in value.columns else ''

if 'GE' in manufacturer:
    if 'SP' not in seq_variant:
        raise ValidationError(f"GE MToff should use SP (SPGR) sequence variant. Found: {seq_variant}")
elif 'SIEMENS' in manufacturer:
    if 'SP' not in seq_variant:
        raise ValidationError(f"Siemens MToff should use SP sequence variant. Found: {seq_variant}")
elif 'PHILIPS' in manufacturer:
    if 'SS' not in seq_variant or 'SP' not in seq_variant:
        raise ValidationError(f"Philips MToff should use SS_SP sequence variant. Found: {seq_variant}")
